/* V65 / One visual language, across all inner pages. */
#surface52{--bg:#faf9f6;--paper:#faf9f6;--surface:#fff;--ink:#252824;--muted:#656861;--red:#cf3d2b;--soft:#eeefe9;--line:#dddfd7;--gutter:clamp(20px,3.35vw,48px);background:var(--paper);color:var(--ink);font:16px/1.65 Arial,Helvetica,sans-serif;-webkit-font-smoothing:antialiased}
#surface52 *{box-sizing:border-box;min-width:0}
#surface52 [hidden]{display:none!important}
#surface52 :is(h1,h2,h3,h4){font-family:Arial,Helvetica,sans-serif;font-weight:400;letter-spacing:-.035em;line-height:1.15;text-wrap:balance;color:var(--ink)}
#surface52 h1{font-size:clamp(42px,4.5vw,66px);line-height:1.05;letter-spacing:-.045em}
