#surface52 p{line-height:1.65;color:var(--muted);text-wrap:pretty}
#surface52 :is(button,input,select,textarea){font-family:Arial,Helvetica,sans-serif}
#surface52 :is(a,button,input,select,textarea):focus-visible{outline:2px solid var(--red);outline-offset:4px}
#surface52 img{max-width:100%}
#surface52 .wrap{width:min(1280px,calc(100% - var(--gutter)*2));margin-inline:auto}
#surface52 .crumb{font-size:12px;color:var(--muted);margin:24px 0 32px}
#surface52 .eyebrow{font-size:11px;line-height:1.5;font-weight:700;letter-spacing:.13em;color:var(--red);margin-bottom:20px;text-transform:uppercase}
#surface52 :is(.lead,.hero .lead){font-size:18px;line-height:1.65;max-width:52ch;margin-block:24px 28px}
