#surface52 .btn:hover{box-shadow:0 4px 16px #25282412;filter:none}
#surface52 :is(.btn.secondary,.btn.light):hover{background:var(--soft);border-color:#b8bcb2}
#surface52 .btn:disabled{opacity:.4;box-shadow:none}
#surface52 :is(.textlink,.link){font-size:14px;line-height:1.5;text-underline-offset:5px}
#surface52 :is(.textlink,.link):hover{color:var(--red)}
#surface52 :is(input:not([type=checkbox]):not([type=radio]),select,textarea){background:#fff;border:1px solid var(--line);color:var(--ink);border-radius:8px;min-height:44px;padding:11px 12px;font-size:14px;max-width:100%}
#surface52 input[type=checkbox],#surface52 input[type=radio]{accent-color:var(--red)}
#surface52 :is(.pill,.pills>a,.catalogtabs>a){border-radius:24px;border:1px solid var(--line);background:transparent;color:var(--ink);font-size:13px;padding:9px 16px;line-height:1.45}
