#surface52 :is(.notice,.adapt-notice,.demo50){background:transparent;border:0;border-left:2px solid var(--line);padding:10px 14px;color:var(--muted);font-size:12px;line-height:1.6}
#surface52 dialog{border:1px solid var(--line);background:var(--paper);border-radius:16px;padding:28px;color:var(--ink);max-width:calc(100% - 28px);max-height:88dvh;overflow:auto;box-shadow:0 24px 100px #25282433}
