#surface52 :is(.formbox,.filterbox){background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px}
#surface52 .consent{font-size:12px!important;color:var(--muted)!important}
#surface52 :is(.faq details,.cpr-contents){border-top:1px solid var(--line);padding:22px 24px}
