#surface52 footer{background:var(--ink);color:#fff;margin-top:88px;padding:48px 0;border:0}
#surface52 footer :is(p,a,.logo,.brand){color:#e2e4dc}
#surface52 footer .wrap{display:flex;align-items:start;justify-content:space-between;gap:32px;flex-wrap:wrap}
#surface52 footer p{font-size:13px}
#surface52 footer .btn{background:#fff;color:var(--ink);border-color:#fff}
#surface52 dialog footer{margin:18px 0 0;padding:0;background:transparent;color:var(--ink)}
#surface52 .story-media60{border-radius:12px;background:var(--soft);overflow:hidden}
#surface52 .story-copy60 h3{font-size:23px}
#surface52 .story-copy60 p{color:var(--muted);font-size:14px}
#surface52 .story-play60{background:#252824df;border-radius:8px}
#surface52 .story-play60 span{color:#fff}
