@media(max-width:900px){#surface52 .section{padding-top:64px}#surface52 :is(.row,.head,.section-heading){gap:24px}#surface52 .formbox{padding:24px}}
@media(max-width:650px){#surface52 h1{font-size:40px}#surface52 h2{font-size:32px}#surface52 h3{font-size:22px}#surface52 :is(.lead,.hero .lead){font-size:16px}#surface52 .section{padding-top:52px}#surface52 :is(.band,.come,.adapt-new){padding:24px;gap:20px}#surface52 :is(.band,.come){display:block}#surface52 .band>.btn,#surface52 .come>.btn{margin-top:20px}#surface52 :is(.row,.head,.section-heading){align-items:start;flex-direction:column;gap:18px}#surface52 footer .wrap{flex-direction:column}#surface52 footer{margin-top:56px;padding:36px 0}#surface52 .faq details{padding:18px 14px}#surface52 .faq summary{font-size:16px}#surface52 .formbox{padding:22px}#surface52 dialog{padding:22px}#surface52 .crumb{margin:20px 0 24px}}
