#surface52 h1{font-size:clamp(42px,4.5vw,66px);line-height:1.05;letter-spacing:-.045em}
#surface52 h2{font-size:clamp(32px,3.25vw,46px);max-width:24ch}
#surface52 h3{font-size:24px;line-height:1.25}
#surface52 h4{font-size:19px}
#surface52 p{line-height:1.65;color:var(--muted);text-wrap:pretty}
