#surface52 .btn:hover{box-shadow:0 4px 16px #25282412;filter:none}
#surface52 :is(.btn.secondary,.btn.light):hover{background:var(--soft);border-color:#b8bcb2}
#surface52 .btn:disabled{opacity:.4;box-shadow:none}
#surface52 :is(.textlink,.link){font-size:14px;line-height:1.5;text-underline-offset:5px}
#surface52 :is(.textlink,.link):hover{color:var(--red)}
#surface52 :is(input:not([type=checkbox]):not([type=radio]),select,textarea){background:#fff;border:1px solid var(--line);color:var(--ink);border-radius:8px;min-height:44px;padding:11px 12px;font-size:14px;max-width:100%}
#surface52 input[type=checkbox],#surface52 input[type=radio]{accent-color:var(--red)}
#surface52 :is(.pill,.pills>a,.catalogtabs>a){border-radius:24px;border:1px solid var(--line);background:transparent;color:var(--ink);font-size:13px;padding:9px 16px;line-height:1.45}
#surface52 :is(.pill.active,.pills>a.active,.catalogtabs>a.active,.pill[aria-pressed=true]){background:var(--ink);border-color:var(--ink);color:#fff}
#surface52 :is(.tiers,.adapt-levels){display:flex;gap:4px;padding:5px;background:var(--soft);border-radius:10px;margin-block:20px}
#surface52 :is(.tiers,.adapt-levels)>button{flex:1;border:0;border-radius:7px;padding:11px 7px;font-size:13px;line-height:1.35;background:transparent;color:var(--muted)}
#surface52 :is(.tiers,.adapt-levels)>button:is(.active,[aria-pressed=true]){background:#fff;color:var(--ink);box-shadow:0 2px 6px #2528240a}
#surface52 .tiers small{display:block;font-size:10px}
#surface52 :is(.palette,.meta){font-size:12px;color:var(--muted)}
#surface52 .swatches{gap:5px}
#surface52 .swatches i{width:22px;height:22px;border-radius:5px;border:1px solid #2528240a}
#surface52 .heart{width:40px;height:40px;border:0;background:#fffffff2;color:var(--ink);border-radius:50%;box-shadow:0 2px 12px #2528240c}
