#surface52 :is(.band,.adapt-new,.come){background:var(--soft);border:0;border-radius:12px;padding:28px 32px;gap:32px}
#surface52 .band h3{font-size:26px;margin-bottom:10px}
#surface52 .band p{font-size:14px;max-width:65ch}
#surface52 :is(.notice,.adapt-notice,.demo50){background:transparent;border:0;border-left:2px solid var(--line);padding:10px 14px;color:var(--muted);font-size:12px;line-height:1.6}
#surface52 dialog{border:1px solid var(--line);background:var(--paper);border-radius:16px;padding:28px;color:var(--ink);max-width:calc(100% - 28px);max-height:88dvh;overflow:auto;box-shadow:0 24px 100px #25282433}
#surface52 dialog::backdrop{background:#25282488;backdrop-filter:blur(5px)}
#surface52 dialog .close{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;background:#fff;font-size:25px;color:var(--ink);display:flex;align-items:center;justify-content:center}
#surface52 :is(.replacement-card,.pick-card){background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden}
#surface52 :is(.replacement-card,.pick-card)[aria-pressed=true]{border-color:var(--red);outline:1px solid var(--red)}
#surface52 :is(.replacement-card,.pick-card) h3{font-size:17px}
#surface52 :is(.formbox,.filterbox){background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px}
#surface52 .consent{font-size:12px!important;color:var(--muted)!important}
#surface52 :is(.faq details,.cpr-contents){border-top:1px solid var(--line);padding:22px 24px}
#surface52 :is(.faq summary,.cpr-contents summary){font-size:17px;line-height:1.5;gap:24px}
#surface52 :is(.faq details[open],.cpr-contents[open]){background:var(--soft);border-radius:8px}
#surface52 .faq details p{font-size:15px;max-width:70ch}
#surface52 footer{background:var(--ink);color:#fff;margin-top:88px;padding:48px 0;border:0}
#surface52 footer :is(p,a,.logo,.brand){color:#e2e4dc}
#surface52 footer .wrap{display:flex;align-items:start;justify-content:space-between;gap:32px;flex-wrap:wrap}
#surface52 footer p{font-size:13px}
#surface52 footer .btn{background:#fff;color:var(--ink);border-color:#fff}
#surface52 dialog footer{margin:18px 0 0;padding:0;background:transparent;color:var(--ink)}
#surface52 .story-media60{border-radius:12px;background:var(--soft);overflow:hidden}
#surface52 .story-copy60 h3{font-size:23px}
#surface52 .story-copy60 p{color:var(--muted);font-size:14px}
#surface52 .story-play60{background:#252824df;border-radius:8px}
#surface52 .story-play60 span{color:#fff}
#surface52 .story-error60 a{text-decoration:underline}
@media(max-width:900px){#surface52 .section{padding-top:64px}#surface52 :is(.row,.head,.section-heading){gap:24px}#surface52 .formbox{padding:24px}}
@media(max-width:650px){#surface52 h1{font-size:40px}#surface52 h2{font-size:32px}#surface52 h3{font-size:22px}#surface52 :is(.lead,.hero .lead){font-size:16px}#surface52 .section{padding-top:52px}#surface52 :is(.band,.come,.adapt-new){padding:24px;gap:20px}#surface52 :is(.band,.come){display:block}#surface52 .band>.btn,#surface52 .come>.btn{margin-top:20px}#surface52 :is(.row,.head,.section-heading){align-items:start;flex-direction:column;gap:18px}#surface52 footer .wrap{flex-direction:column}#surface52 footer{margin-top:56px;padding:36px 0}#surface52 .faq details{padding:18px 14px}#surface52 .faq summary{font-size:16px}#surface52 .formbox{padding:22px}#surface52 dialog{padding:22px}#surface52 .crumb{margin:20px 0 24px}}
@media(prefers-reduced-motion:reduce){#surface52 *{scroll-behavior:auto!important;transition:none!important}}

